// The curated tools: per-product routers from tools/ (copies of shared/google-tools, written by
// scripts/google-vendor.ts), plus the two tools that span products.
import { number, object, query, router, string, type RouterChild, type RouterOptions, type QueryContext } from "apps";
import { calendar, listEvents } from "./tools/calendar.js";
import { drive, driveQuery, searchFiles } from "./tools/drive.js";
import { gmail, searchMail } from "./tools/gmail.js";
import { contacts, findPeople } from "./tools/people.js";
import { fanOut, linked, select, type Source } from "./tools/shared.js";
import { sheets } from "./tools/sheets.js";
import { tasks } from "./tools/tasks.js";

const day = 24 * 60 * 60 * 1000;

/** A product's curated tools as one router. */
const mount = <Query, Mutation>(product: {
  readonly tools: Readonly<Record<string, RouterChild<Query, Mutation>>>;
  readonly meta: RouterOptions;
}) =>
  router(product.tools, product.meta);

export const curated = (source: Source) => ({
  accounts: query(
    {
      description: "List the linked Google accounts by address. Tools that take `account` accept one of these addresses.",
      input: object({}),
    },
    async (ctx: QueryContext) => ({
      accounts: (await linked(ctx, source)).map((target) => ({ email: target.email, accountId: target.account.id })),
    }),
  ),
  search: query(
    {
      description:
        "Search everything at once across every linked Google account (or one): mail (Gmail search syntax works), Drive files, calendar events from 90 days back to a year ahead, and contacts. Returns the top matches of each; follow up with the product's own tools.",
      input: object({ query: string({ minLength: 1 }), account: string().optional(), max: number().optional() }),
    },
    async (ctx: QueryContext, input) => {
      const targets = await select(ctx, source, input.account);
      const max = Math.min(Math.max(input.max ?? 5, 1), 25);
      const now = Date.now();
      const [mail, files, events, people] = await Promise.all([
        searchMail(ctx, targets, input.query, max),
        // Gmail operators (from:, is:unread) mean nothing to Drive; search its words only.
        searchFiles(ctx, targets, driveQuery(input.query.replace(/\b[a-z_]+:\S+/gi, "").trim() || input.query, undefined), max),
        listEvents(ctx, targets, now - 90 * day, now + 365 * day, input.query),
        fanOut(targets, (target) => findPeople(ctx, target, input.query, max)),
      ]);
      return {
        mail: mail.threads,
        files: files.files,
        // Nearest to today first, whether past or upcoming.
        events: [...events.events].sort((a, b) => Math.abs(Date.parse(a.start) - now) - Math.abs(Date.parse(b.start) - now)).slice(0, max),
        people: people.items.slice(0, max),
        errors: [...mail.errors, ...files.errors, ...events.errors, ...people.errors],
      };
    },
  ),
  gmail: mount(gmail(source)),
  calendar: mount(calendar(source)),
  drive: mount(drive(source)),
  sheets: mount(sheets(source)),
  contacts: mount(contacts(source)),
  tasks: mount(tasks(source)),
});

import type { AppIcon } from "apps";

// Generated by scripts/icon.ts from the vendor's logo.
export const icons: readonly AppIcon[] = [
  {
    "src": "data:image/svg+xml;base64,",
    "mimeType": "image/svg+xml"
  }
];

import { accountRouter, defineApp, router, withApprovals, type RouterDeclaration } from "apps";
import { always } from "apps/operations/approval";
import { liveOpenapiRouter, type OpenapiToolNamesOptions } from "apps/openapi";
import { icons } from "./icon.js";
import { requirements } from "./provider.js";
import { curated } from "./curated.js";
import { addresses } from "./tools/shared.js";
import { sendLater, sendLaterName } from "./tools/schedule.js";
// products/ holds copies of the single-product packages' sources (scripts/google-vendor.ts).
import { options as calendar } from "./products/calendar/openapi.js";
import { options as contacts } from "./products/contacts/openapi.js";
import * as docs from "./products/docs/tools.js";
import { options as drive } from "./products/drive/openapi.js";
import { options as forms } from "./products/forms/openapi.js";
import { options as gmail } from "./products/gmail/openapi.js";
import * as meet from "./products/meet/tools.js";
import { libraryOptions as photosLibrary, pickerOptions as photosPicker } from "./products/photos/openapi.js";
import { options as sheets } from "./products/sheets/openapi.js";
import * as slides from "./products/slides/tools.js";
import { options as tasks } from "./products/tasks/openapi.js";

const approve = <Query, Mutation>(tools: RouterDeclaration<Query, Mutation>) =>
  withApprovals(tools, (tool) => (tool.kind === "mutation" ? always() : undefined));

const declared = { ...requirements, icons };

export default defineApp(
  declared,
  async ({ user, cache, fetch, signal }) => ({
    tools: router(
      {
        ...curated({
          accounts: user?.accounts.google ?? [],
          address: addresses.userinfo("https://www.googleapis.com/oauth2/v3/userinfo"),
          api: (product) => `api.${product}`,
        }),
        api: router(
          await accountRouter(
            user?.accounts.google ?? [],
            (account) => {
              const token = account.fields.access_token;
              const openapi = (options: OpenapiToolNamesOptions) =>
                approve(liveOpenapiRouter({ ...options, cache, fetch, signal, account }));
              return router({
                gmail: router(openapi(gmail), {
                  title: "Gmail",
                  description: "Messages, threads, drafts, labels, history, filters, send-as aliases and settings.",
                }),
                calendar: router(openapi(calendar), {
                  title: "Google Calendar",
                  description: "Calendars, events, attendees, free/busy availability, sharing and settings.",
                }),
                drive: router(openapi(drive), {
                  title: "Google Drive",
                  description: "Files, folders, shared drives, permissions, comments, replies and revisions.",
                }),
                sheets: router(openapi(sheets), {
                  title: "Google Sheets",
                  description: "Spreadsheets, sheets, cell values, formatting and batch updates.",
                }),
                docs: router(approve(docs.tools(token, fetch, signal)), docs.meta),
                slides: router(approve(slides.tools(token, fetch, signal)), slides.meta),
                forms: router(openapi(forms), {
                  title: "Google Forms",
                  description: "Forms, questions, settings and responses.",
                }),
                tasks: router(openapi(tasks), {
                  title: "Google Tasks",
                  description: "Task lists and tasks.",
                }),
                contacts: router(openapi(contacts), {
                  title: "Google Contacts",
                  description: "Contacts, contact groups, other contacts and the Workspace directory (People API).",
                }),
                meet: router(approve(meet.tools(token, fetch, signal)), meet.meta),
                photos: router(
                  {
                    library: router(openapi(photosLibrary), {
                      title: "Google Photos Library",
                      description: "Albums and media items created by this app; uploads into the library.",
                    }),
                    picker: router(openapi(photosPicker), {
                      title: "Google Photos Picker",
                      description: "Picker sessions where the user selects photos, then the picked items.",
                    }),
                  },
                  { title: "Google Photos", description: "Google Photos Library and Picker APIs." },
                ),
              });
            },
            { signal },
          ),
          {
            title: "Google APIs",
            description:
              "The complete APIs of each Google product, per account: every tool takes accountId (from the top-level accounts tool) and the API's own input.",
          },
        ),
      },
      {
        title: "Google",
        description:
          "Every linked Google account across Gmail, Calendar, Drive, Sheets, Docs, Slides, Forms, Tasks, Contacts, Meet and Photos.",
        instructions:
          "Start with the top-level tools: search, gmail, calendar, drive, sheets, contacts and tasks read across every linked account at once unless `account` (an address) narrows them, and their results name the account each item came from. Pass that account to reads and writes of one item. Use api.<product> only for what the curated tools do not cover.",
        icons,
      },
    ),
    // Scheduled emails are drafts this workflow sends at their time; it is the editable behaviour.
    workflows: { [sendLaterName]: sendLater<typeof declared>((step) => step.user.accounts.google) },
  }),
);

{
  "name": "@executor.sh/google",
  "description": "Every linked Google account across Gmail, Calendar, Drive, Sheets, Docs, Slides, Forms, Tasks, Contacts, Meet and Photos: cross-account search, agenda and availability, plus the complete APIs.",
  "private": true,
  "type": "module",
  "executor": {
    "title": "Google"
  },
  "dependencies": {
    "apps": "0.0.1-beta.104-basalt.16"
  }
}

